insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9786161870638','Make Your Bed เก็บที่นอน ก่อนออกไปเปลี่ยนโลก','William H. McRaven; แปลโดย บุษกร เมธางกูรเสรี','อมรินทร์ How to','Thai','5a339538-6307-407d-88ba-d29749a4a98b',$d$<h2>รายละเอียด : เก็บที่นอน ก่อนออกไปเปลี่ยนโลก</h2><p>บทเรียนเรียบง่ายจากประสบการณ์ของอดีตผู้บัญชาการหน่วยซีล เริ่มจากการเก็บที่นอนให้เรียบร้อย แล้วต่อยอดวินัย ความรับผิดชอบ ความกล้าหาญ และการไม่ยอมแพ้ เพื่อเปลี่ยนชีวิตตนเองและสร้างผลกระทบที่ดีต่อโลก</p>$d$,null,'2025-01-01','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9786161870638.jpg',false) on conflict (isbn) do nothing;
