insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9789749875445','พลังจิตใต้สำนึก ฉบับปรับปรุง','Joseph Murphy; revised by Ian McMahan; แปลโดย ทศยุทธ','เรือนบุญ','Thai','5a339538-6307-407d-88ba-d29749a4a98b',$d$<h2>รายละเอียด : พลังจิตใต้สำนึก ฉบับปรับปรุง</h2><p>แนวทางทำความเข้าใจพลังของจิตใต้สำนึกและนำความคิด ความเชื่อ และการสร้างภาพในใจมาใช้เปลี่ยนนิสัย เสริมความมั่นใจ พัฒนาความสัมพันธ์ สุขภาพ การงาน และความสำเร็จ ผ่านหลักคิดและตัวอย่างที่นำไปฝึกใช้ได้</p>$d$,338,'2015-01-01','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9789749875445.jpg',false) on conflict (isbn) do nothing;
