('9780735204553','The Power of Your Subconscious Mind','Joseph Murphy','TarcherPerigee','English','5a339538-6307-407d-88ba-d29749a4a98b',$d$<h2>Description</h2><p>The edition authorized by the Dr. Joseph Murphy Trust explains how habitual thoughts and beliefs shape experience, and presents practical techniques intended to apply the subconscious mind to confidence, relationships, health, work, and personal achievement.</p>$d$,null,null,'https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9780735204553.jpg',false) on conflict (isbn) do nothing;
insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9786161860226','กฎเหนือกฎ เพื่อชีวิตที่มีความหมาย (Beyond Order: 12 More Rules for Life)','Jordan B. Peterson; แปลโดย พอหทัย อภิรัชฎาพร','อมรินทร์ How to','Thai','5a339538-6307-407d-88ba-d29749a4a98b',$d$<h2>รายละเอียด : กฎเหนือกฎ เพื่อชีวิตที่มีความหมาย</h2><p>อีก 12 กฎสำหรับเผชิญโลกที่ซับซ้อน ตั้งแต่การเห็นคุณค่าของสถาบันและผลงานสร้างสรรค์ การจินตนาการถึงตนเองในอนาคต ไปจนถึงการไม่ซ่อนปัญหาไว้ในความคลุมเครือ หนังสือชวนหาสมดุลระหว่างความโกลาหลกับระเบียบเพื่อสร้างความหมายแก่ชีวิต</p>$d$,456,'2023-11-01','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9786161860226.jpg',false) on conflict (isbn) do nothing;
insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
