insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9786166090987','จิตวิทยาแค่ 1% ทำให้คุณ “เหนือ” คน','เฌอมาณย์ รัตนพงศ์ตระกูล','Double Days','Thai','5a339538-6307-407d-88ba-d29749a4a98b',$d$<h2>รายละเอียด : จิตวิทยาแค่ 1% ทำให้คุณ “เหนือ” คน</h2><p>รวบรวมหลักจิตวิทยา ไหวพริบ และกลยุทธ์ในการเข้าใจและเอาชนะใจคน เพื่อพัฒนาการสื่อสาร การทำงานร่วมกับผู้อื่น การสร้างเพื่อนและคอนเน็กชัน ตลอดจนเพิ่มโอกาสความสำเร็จในงานและธุรกิจ</p>$d$,171,'2025-01-01','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9786166090987.webp',false) on conflict (isbn) do nothing;
insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9786169317364','เศรษฐกิจโลก 1,000 ปี เรียนรู้อดีต เพื่อเข้าใจอนาคต','ลงทุนแมน','ลงทุนแมน','Thai','3052508c-65ca-4fbf-9aa4-6787ef246869',$d$<h2>รายละเอียด : เศรษฐกิจโลก 1,000 ปี</h2><p>ถ่ายทอดประวัติศาสตร์เศรษฐกิจโลกผ่านความรุ่งเรืองและร่วงโรยของอาณาจักร ประเทศ เทคโนโลยี การค้า การเงิน บริษัท และตลาดทุน เพื่อเชื่อมโยงเหตุการณ์ในอดีตกับโครงสร้างเศรษฐกิจปัจจุบันและช่วยให้มองอนาคตได้ชัดขึ้น</p>$d$,224,'2020-01-01','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9786169317364.jpg',false) on conflict (isbn) do nothing;
insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9786160851775','The Fiat Standard ระบบการเงินบังคับผูกขาด สู่อารยธรรมแห่งการเป็นทาสในเรือนเบี้ย','Saifedean Ammous; เรียบเรียงโดย พิริยะ สัมพันธารักษ์, พีรพัฒน์ หาญคงแก้ว, จิงโจ้ Right Shift และ สมบิ๊ก Right Shift','ซีเอ็ดยูเคชั่น','Thai','3052508c-65ca-4fbf-9aa4-6787ef246869',$d$<h2>รายละเอียด : The Fiat Standard</h2><p>อธิบายกำเนิดและกลไกของเงินเฟียต เหตุผลที่ระบบนี้เข้ามาแทนมาตรฐานทองคำ ผลกระทบต่อเศรษฐกิจ สังคม และหนี้สิน พร้อมเปรียบเทียบโครงสร้างของเงินเฟียตกับบิตคอยน์เพื่อทำความเข้าใจวิวัฒนาการและภูมิศาสตร์ของเงิน</p>$d$,568,'2024-01-01','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9786160851775.jpg',false) on conflict (isbn) do nothing;
insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9786169385462','The Effective Executive ผู้บริหารทรงประสิทธิผล','Peter F. Drucker','Openbooks','Thai','9ab5d90a-12d8-4ed1-b997-21aa7883cffa',$d$<h2>รายละเอียด : ผู้บริหารทรงประสิทธิผล</h2><p>แนวทางบริหารตนเองเพื่อสร้างผลงานที่มีประสิทธิผล ตั้งแต่การรู้ว่าเวลาถูกใช้ไปกับอะไร การมุ่งผลลัพธ์ภายนอก การต่อยอดจุดแข็ง การจัดลำดับความสำคัญ และการตัดสินใจอย่างเป็นระบบ ใช้ได้ทั้งผู้บริหาร พนักงาน และผู้ที่ต้องการก้าวหน้าในการทำงาน</p>$d$,null,'2024-03-29','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9786169385462.jpg',false) on conflict (isbn) do nothing;
insert into public.books (isbn,title,author,publisher,language,category_id,description,pages,publication_date,cover_image_url,is_active) values
('9786161851552','รวยมาตั้งแต่จิตใต้สำนึก (Wealthinking)','Kelly Choi; แปลโดย วาสนา จันทะทัง','อมรินทร์ How to','Thai','3052508c-65ca-4fbf-9aa4-6787ef246869',$d$<h2>รายละเอียด : รวยมาตั้งแต่จิตใต้สำนึก</h2><p>เคลลี ชเว ถ่ายทอดบทเรียนจากชีวิตที่เคยยากจนและมีหนี้สิน สู่การศึกษาวิธีคิดของคนมั่งคั่งกว่าหนึ่งพันคน หนังสือชวนปลูกจิตใต้สำนึกแบบใหม่ผ่านการตั้งเป้าหมาย การสร้างภาพในใจ และการลงมือทำอย่างต่อเนื่อง เพื่อสร้างความมั่งคั่งจากภายในสู่ชีวิตจริง</p>$d$,208,'2022-08-01','https://bzyvzftnfuuxcseuqrnj.supabase.co/storage/v1/object/public/books/covers/9786161851552.jpg',false) on conflict (isbn) do nothing;
